function [nrm] = drag_array_normal(axis, s_hat_b)
%DRAG_ARRAY_NORMAL  arrayNormal(axis, sHat_b) of dgeom: the best-lit normal of an array turning about axis, towards s_hat_b (Octave's
%   unit vectors).
%   axis: real[1][3] (passed a plain number)
%   s_hat_b: real[1][3] (passed a plain number)
%   returns nrm: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    nrm = zeros(3, 1);
    ax = asils.models.drag.ounit(axis);
    d = (s_hat_b(1)*ax(1) + s_hat_b(2)*ax(2) + s_hat_b(3)*ax(3));
    proj = [(s_hat_b(1) - (d * ax(1))); (s_hat_b(2) - (d * ax(2))); (s_hat_b(3) - (d * ax(3)))];
    if (asils.models.gravity.onorm(proj) < 1e-9)
        t = [1; 0; 0];
        if (asils.pc.fabs(ax(1)) > 0.9)
            t = [0; 1; 0];
        end
        d2 = (t(1)*ax(1) + t(2)*ax(2) + t(3)*ax(3));
        proj = [(t(1) - (d2 * ax(1))); (t(2) - (d2 * ax(2))); (t(3) - (d2 * ax(3)))];
    end
    nrm = asils.models.drag.ounit(proj);
end
